curl -s "https://quay.io/api/v1/repository/biocontainers/biopython/tag/?limit=5&onlyActiveTags=true" | python3 -c "
import sys, json
data = json.load(sys.stdin)
print(type(data))
if isinstance(data, dict):
    print(list(data.keys())[:10])
    tags = data.get('tags', [])
    if isinstance(tags, list):
        for t in tags[:5]:
            print(t.get('name', t))
    elif isinstance(tags, dict):
        for k in list(tags.keys())[:5]:
            print(k)
elif isinstance(data, list):
    for item in data[:5]:
        print(item.get('name', str(item))[:100])
"

