events.command:
curl -s "https://quay.io/api/v1/repository/biocontainers/phykit/tag/?limit=20&onlyActiveTags=true" | python3 -c "
import sys, json
data = json.load(sys.stdin)
tags = data.get('tags', {})
if isinstance(tags, dict):
    for k, v in sorted(tags.items()):
        print(f'{k}  (modified: {v.get(\"last_modified\",\"?\")})')
    print(f'Total: {len(tags)} tags')
elif isinstance(tags, list):
    for t in tags[:20]:
        print(json.dumps(t, indent=2)[:300])
        print('---')
        "

